17	/**
18	 * Generic DTO that wraps a paginated collection and its accompanying metadata.
19	 * <p>
20	 * This DTO is deliberately free of framework–specific Page implementations so that it
21	 * can be re–used across the REST, GraphQL and gRPC adapters without creating
22	 * unnecessary transitive dependencies.
23	 *
24	 * @param <T> the element type contained in the page
25	 */
26	@JsonInclude(JsonInclude.Include.NON_NULL)
27	@Schema(description = "A generic paginated result wrapper")
28	public final class PaginatedResponse<T> implements Serializable {
29	
30	    @Serial
