60	    /**
61	     * Factory helper to build a {@link PaginatedResponse} from raw pagination values.
62	     *
63	     * @param content       list of items for the current page
64	     * @param totalElements total amount of elements on all pages
65	     * @param page          zero–based index of the current page
66	     * @param size          requested size of a single page
67	     * @param requestUri    URI of the current request (used for link generation)
68	     * @param <T>           type of the content elements
69	     * @return a fully–populated {@link PaginatedResponse}
70	     */
71	    public static <T> PaginatedResponse<T> of(final List<T> content,
72	                                              final long totalElements,
73	                                              final int page,
74	                                              final int size,
75	                                              final URI requestUri) {
76	        Objects.requireNonNull(content, "content list must not be null");
77	        Objects.requireNonNull(requestUri, "requestUri must not be null");
78	
79	        int safeSize = Math.max(size, 1);
80	        int totalPages = (int) Math.ceil((double) totalElements / safeSize);
81	        int safePage = Math.max(page, 0);
82	
83	        PageMeta meta = new PageMeta(
84	                totalElements,
85	                totalPages,
86	                safePage,
87	                safeSize,
88	                safePage == 0,
89	                safePage >= totalPages - 1
90	        );
91	
92	        List<Link> navLinks = createNavigationLinks(requestUri, safePage, totalPages, safeSize);
93	
94	        return new Builder<T>()
95	                .withContent(content)
96	                .withMeta(meta)
97	                .withLinks(navLinks)
98	                .build();
99	    }
100	
101	    private static List<Link> createNavigationLinks(URI baseUri,
102	                                                    int page,
103	                                                    int totalPages,
104	                                                    int size) {
105	        List<Link> result = new ArrayList<>(4);
106	
107	        // self
108	        result.add(Link.self(buildUri(baseUri, page, size)));
109	
110	        // first
111	        result.add(Link.first(buildUri(baseUri, 0, size)));
112	
113	        // previous
114	        if (page > 0) {
115	            result.add(Link.prev(buildUri(baseUri, page - 1, size)));
116	        }
117	
118	        // next
119	        if (page + 1 < totalPages) {
120	            result.add(Link.next(buildUri(baseUri, page + 1, size)));
121	        }
122	
123	        // last
124	        result.add(Link.last(buildUri(baseUri, totalPages - 1, size)));
125	
126	        return result;
127	    }
