129	    private static URI buildUri(URI baseUri, int page, int size) {
130	        // NOTE: This manual URI manipulation avoids adding the rather heavy Spring UriComponentsBuilder dependency.
131	        String query = String.format("page=%d&size=%d", page, size);
132	        return URI.create(baseUri.getPath() + '?' + query);
133	    }
